import { fixMojibake } from "../text";
import type { Channel, RawMessage, ThreadPart } from "../types";
import { channelFromPath, classify, locate, type MetaMessage } from "./meta";

/**
 * Facebook / Instagram "Download your information" in HTML format (the
 * default choice). Learned from a real Facebook export (Oct 2026, 519 chats):
 *
 *   <title>/<h1>  conversation title (the other person in a 1:1 chat)
 *   <aside>       "Generated by <account owner> on <date> at <time> UTC+01:00"
 *   <main>
 *     <section>   one message
 *       <h2>      sender name
 *       <div>     message text; <img>/<video> for media, <a> for links,
 *                 <ul><li> for reactions (not part of the message)
 *       <footer>  "Mar 05, 2026 4:44:47 pm" (time in the zone from <aside>)
 *
 * Class names are obfuscated and change, so we rely on the tags only. This
 * runs in a Web Worker (no DOMParser there), so it is a small tag scanner.
 */

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

export function decodeEntities(s: string): string {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e: string) => {
    if (e[0] === "#") {
      const n = e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(n) ? String.fromCodePoint(n) : m;
    }
    return ENTITIES[e.toLowerCase()] ?? m;
  });
}

const MONTHS: Record<string, number> = {
  jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, sept: 8, oct: 9, nov: 10, dec: 11,
};

/** "Mar 05, 2026 4:44:47 pm", "March 5, 2026 at 16:44" → epoch ms (given the export's UTC offset). */
export function parseMetaDate(s: string, offsetMinutes: number): number {
  const m = /([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4}),?\s+(?:at\s+)?(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap]\.?m\.?)?/i.exec(
    s.replace(/[  ]/g, " "),
  );
  if (!m) return NaN;
  const month = MONTHS[m[1]!.slice(0, 4).toLowerCase()] ?? MONTHS[m[1]!.slice(0, 3).toLowerCase()];
  if (month === undefined) return NaN;
  let h = Number(m[4]);
  const ap = m[7]?.toLowerCase().replace(/\./g, "");
  if (ap === "pm" && h < 12) h += 12;
  if (ap === "am" && h === 12) h = 0;
  return Date.UTC(Number(m[3]), month, Number(m[2]), h, Number(m[5]), Number(m[6] ?? 0)) - offsetMinutes * 60_000;
}

/** "UTC+01:00" / "UTC-4" in the export header → minutes east of UTC. */
export function offsetFromHeader(s: string): number | null {
  const m = /UTC\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?/.exec(s);
  if (!m) return /UTC\b/.test(s) ? 0 : null;
  const v = Number(m[2]) * 60 + Number(m[3] ?? 0);
  return m[1] === "-" ? -v : v;
}

interface Section {
  sender: string;
  text: string[];
  footer: string;
  img: boolean;
  video: boolean;
  links: string[];
}

export function looksLikeMetaHtml(html: string): boolean {
  // A page may hold only a system entry with no sender (<h2>): still a conversation page.
  return /<section\b/i.test(html) && /<footer\b/i.test(html);
}

export interface MetaHtmlResult {
  part: ThreadPart;
  /** The account owner, from "Generated by …" (English exports). */
  owner?: string;
}

export function parseMetaHtml(
  html: string,
  path: string,
  opts: { hint?: Channel; timeZoneOffsetMinutes?: number } = {},
): MetaHtmlResult | null {
  const sections: Section[] = [];
  let cur: Section | null = null;
  let where: "h1" | "title" | "aside" | "h2" | "body" | "footer" | null = null;
  let skip = 0;
  let ulDepth = 0;
  let title = "";
  let aside = "";

  const TAG = /<(\/?)([a-zA-Z0-9]+)((?:[^>"']|"[^"]*"|'[^']*')*)>|<!--[\s\S]*?-->|([^<]+)/g;
  for (let m = TAG.exec(html); m; m = TAG.exec(html)) {
    if (m[4] !== undefined) {
      if (skip) continue;
      const text = decodeEntities(m[4]).replace(/\s+/g, " ").trim();
      if (!text) continue;
      if (where === "title" || where === "h1") title ||= text;
      else if (where === "aside") aside += `${text} `;
      else if (cur && where === "h2") cur.sender += text;
      else if (cur && where === "footer") cur.footer += `${text} `;
      else if (cur && where === "body" && ulDepth === 0) cur.text.push(text);
      continue;
    }
    if (!m[2]) continue;
    const closing = m[1] === "/";
    const tag = m[2].toLowerCase();
    if (tag === "style" || tag === "script") {
      skip += closing ? -1 : 1;
      continue;
    }
    if (!closing) {
      if (tag === "title") where = "title";
      else if (tag === "h1") where = "h1";
      else if (tag === "aside") where = "aside";
      else if (tag === "section") {
        cur = { sender: "", text: [], footer: "", img: false, video: false, links: [] };
        sections.push(cur);
        where = null;
      } else if (cur) {
        if (tag === "h2") where = "h2";
        else if (tag === "footer") where = "footer";
        else if (where === null || where === "h2") {
          if (tag !== "br") where = "body";
        }
        if (tag === "ul") ulDepth++;
        if (tag === "img") cur.img = true;
        if (tag === "video" || tag === "audio") cur.video = true;
        if (tag === "a") {
          const href = /href\s*=\s*"([^"]*)"/i.exec(m[3] ?? "")?.[1];
          if (href && /^https?:/i.test(href)) cur.links.push(decodeEntities(href));
        }
      }
    } else {
      if (tag === "title" || tag === "h1" || tag === "aside" || tag === "h2" || tag === "footer") where = cur ? "body" : null;
      if (tag === "ul" && ulDepth > 0) ulDepth--;
      if (tag === "section") {
        cur = null;
        where = null;
      }
    }
  }

  if (!sections.length) return null;
  const offset = offsetFromHeader(aside) ?? opts.timeZoneOffsetMinutes ?? 0;
  const messages: RawMessage[] = [];
  const senders = new Set<string>();
  for (const s of sections) {
    const at = parseMetaDate(s.footer, offset);
    if (Number.isNaN(at)) continue;
    const sender = fixMojibake(s.sender.trim()) || null;
    const text = fixMojibake(s.text.join("\n").trim());
    const meta: MetaMessage = {
      content: text,
      photos: s.img ? [1] : undefined,
      videos: s.video ? [1] : undefined,
      share: s.links.length ? { link: s.links[0] } : undefined,
    };
    const kind = classify(meta, text);
    if (sender) senders.add(sender);
    messages.push({ sender, at, text, kind });
  }

  const channel = channelFromPath(path, opts.hint);
  const { key, folder } = locate(path);
  const cleanTitle = fixMojibake(title.trim());
  const participants = [...senders];
  if (cleanTitle && !participants.includes(cleanTitle) && participants.length <= 1) participants.push(cleanTitle);
  const owner = /^Generated by (.+?) on /i.exec(aside.trim())?.[1]?.trim();
  return {
    part: {
      channel,
      threadKey: `${channel}:${key ?? `${cleanTitle}|${participants.sort().join("|")}`}`,
      title: cleanTitle || participants.join(", "),
      participants,
      folder,
      // In a 1:1 chat the page is titled with the other person.
      counterpart: cleanTitle && cleanTitle !== owner ? cleanTitle : undefined,
      messages,
    },
    owner: owner ? fixMojibake(owner) : undefined,
  };
}
